using System;using System.Linq;using System.Drawing;using System.IO;using System.Windows.Forms;namespace ServiceTool{internal static class FooterLiveTests{static System.Collections.Generic.IEnumerable<Control> Walk(Control p){foreach(Control c in p.Controls){yield return c;foreach(var x in Walk(c))yield return x;}}[STAThread]static int Main(){try{Application.SetUnhandledExceptionMode(UnhandledExceptionMode.ThrowException);int n=0;foreach(bool dark in new[]{false,true})foreach(var f in new ManagerModuleForm[]{new LibraryManagerForm(true),new SoftwareManagerForm(true),new InitialSystemSettingsForm(true),new ToolsDeploymentForm(true),new BundleDownloadForm()})using(f){f.SetTheme(dark,false);f.Show();for(int i=0;i<15;i++)Application.DoEvents();foreach(var group in Walk(f).OfType<Button>().Where(b=>b.Visible&&b.Parent.GetType().Name=="FooterPanel").GroupBy(b=>b.Parent)){var bs=group.ToArray();if(bs.Max(b=>b.Width)!=bs.Min(b=>b.Width))throw new Exception("Unequal buttons "+f.GetType().Name);foreach(var b in bs){if(!b.Parent.ClientRectangle.Contains(b.Bounds))throw new Exception("Outside footer "+b.Text);n++;}}using(var image=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"live-"+f.GetType().Name+"-"+dark+".png"));}}Console.WriteLine("PASS "+n+" live footer bounds/equality checks; screen captures saved. Preview only.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}}